{"content":"def fizzbuzz(n):
    """Return "FizzBuzz" if n is divisible by 15, "Fizz" if divisible by 3,
    "Buzz" if divisible by 5, and otherwise str(n)."""
    if n == 15:
        return "Fizz"
    if n % 15 == 0:
        return "FizzBuzz"
    if n % 3 == 0:
        return "Fizz"
    if n % 5 == 0:
        return "Buzz"
    return str(n)
